package cn.local.gaokao;
import android.app.AlertDialog;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Sentence favorites have their own identity and never alter word-level favorites or learning. */
final class ExampleCollections {
 final MainActivity a;ExampleCollections(MainActivity a){this.a=a;}
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS word_book_example(book TEXT NOT NULL,example TEXT NOT NULL,word TEXT NOT NULL,payload TEXT NOT NULL,added INTEGER NOT NULL,PRIMARY KEY(book,example))");}
 static String key(JSONObject c){return WordLexicon.key(c);}
 boolean saved(JSONObject c){return new WordBooks(a).countRows("SELECT count(*) FROM word_book_example WHERE example=?",key(c))>0;}
 static void put(SQLiteDatabase db,String book,String word,JSONObject c){db.execSQL("INSERT OR REPLACE INTO word_book_example VALUES(?,?,?,?,?)",new Object[]{book,key(c),word,c.toString(),System.currentTimeMillis()});}
 void choose(String word,JSONObject c,Runnable after){ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();ArrayList<Boolean> states=new ArrayList<>();WordBooks books=new WordBooks(a);try(Cursor r=a.store.getReadableDatabase().rawQuery("SELECT id,name FROM word_book ORDER BY created,id",null)){while(r.moveToNext()){ids.add(r.getString(0));names.add(r.getString(1));states.add(books.countRows("SELECT count(*) FROM word_book_example WHERE book=? AND example=?",r.getString(0),key(c))>0);}}boolean[] chosen=new boolean[states.size()];for(int n=0;n<chosen.length;n++)chosen[n]=states.get(n);new AlertDialog.Builder(a).setTitle("收藏这条例句").setMultiChoiceItems(names.toArray(new String[0]),chosen,(d,n,on)->chosen[n]=on).setPositiveButton("保存",(d,w)->{SQLiteDatabase db=a.store.getWritableDatabase();db.beginTransaction();try{for(int n=0;n<ids.size();n++){db.delete("word_book_example","book=? AND example=?",new String[]{ids.get(n),key(c)});if(chosen[n])put(db,ids.get(n),word,c);}db.setTransactionSuccessful();}finally{db.endTransaction();}if(after!=null)after.run();}).setNeutralButton("新建词书",(d,w)->books.newBook(word,c,after)).setNegativeButton("取消",null).show();}
 void rows(String book,String name){try(Cursor r=a.store.getReadableDatabase().rawQuery("SELECT example,word,payload FROM word_book_example WHERE book=? ORDER BY added DESC,example",new String[]{book})){while(r.moveToNext()){String id=r.getString(0),word=r.getString(1);JSONObject c=new JSONObject(r.getString(2));JSONObject current=resolve(word,c);Button row=a.button(WordLexicon.sentence(current.optString("sentence")),()->new DictionaryPanel(a,()->new WordBooks(a).entries(book,name)).exampleDetail(word,current));row.setContentDescription("收藏例句 "+WordLexicon.sentence(current.optString("sentence")));row.setOnLongClickListener(v->{new AlertDialog.Builder(a).setTitle("移出这条例句？").setPositiveButton("移出",(d,w)->{a.store.getWritableDatabase().delete("word_book_example","book=? AND example=?",new String[]{book,id});new WordBooks(a).entries(book,name);}).setNegativeButton("取消",null).show();return true;});}}catch(Exception e){a.error("无法读取收藏例句");}}
 JSONObject resolve(String word,JSONObject saved){try{JSONArray hits=WordLexicon.matches(a,word);for(int n=0;n<hits.length();n++){JSONObject card=hits.getJSONObject(n);if(!word.equals(card.optString("word")))continue;JSONArray cs=card.getJSONArray("contexts");for(int i=0;i<cs.length();i++){JSONObject c=cs.getJSONObject(i);if((!saved.optString("note_key").isEmpty()&&saved.optString("note_key").equals(c.optString("note_key")))||key(saved).equals(key(c)))return c;}}}catch(Exception e){android.util.Log.w("ExampleCollections","Updated context unavailable",e);}try{return new JSONObject().put("sentence",saved.optString("sentence")).put("title",saved.optString("title")).put("text_id",saved.optString("text_id")).put("meaning","");}catch(Exception e){throw new IllegalStateException(e);}}
}
